(()=>{'use strict';
const DB=window.ELEKTRO_DATA;const modules=DB.modules,lessons=DB.lessons;
const q=(s)=>document.querySelector(s), $$=(s)=>[...document.querySelectorAll(s)];
const safe=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage=window.ElektroStorage;
const fresh=()=>({version:2,activeLesson:lessons[0].id,activeModule:null,tab:'inhalt',view:'dashboard',year:1,lessonDone:[],quizAnswers:{},notes:{},audioIndex:{},audioTime:{},reviews:{},attemptHistory:[],quizAttemptDone:{},exerciseProgress:{},settings:{rate:1,voice:''},updated:null});
let state=fresh(),activeTab='inhalt',isSpeaking=false,isPaused=false,runId=0,speechChunks=[],liveLessonId=null;
let pwaRegistration=null,waitingWorker=null,updateAccepted=false;
const spaced=window.ElektroReviews, audioFiles=window.ElektroAudio, cloud=window.ElektroCloud, exercises=window.ELEKTRO_EXERCISES||[];
let audioAvailable=false,audioError='',audioPositionTick=0,exSelected=1,exerciseShow={},cloudNotice='';
const lessonIDs=new Set(lessons.map(l=>l.id));
const moduleIDs=new Set(modules.map(m=>m.id));
function normalize(raw){
 const x=raw&&typeof raw==='object'?raw:{};const obj=fresh();
 obj.activeLesson=lessonIDs.has(x.activeLesson)?x.activeLesson:obj.activeLesson;
 obj.activeModule=moduleIDs.has(x.activeModule)?x.activeModule:null;
 obj.tab=['inhalt','praxis','quiz'].includes(x.tab)?x.tab:'inhalt';
 obj.view=['dashboard','year','lesson','module','settings','sources','practice','reviews','stats','cloud'].includes(x.view)?x.view:'dashboard';
 obj.year=[1,2,3,4].includes(Number(x.year))?Number(x.year):1;
 obj.lessonDone=Array.isArray(x.lessonDone)?[...new Set(x.lessonDone.filter(id=>lessonIDs.has(id)))]:[];
 for(const [id,answers] of Object.entries(x.quizAnswers||{})){
  if(!lessonIDs.has(id)||!answers||typeof answers!=='object')continue;
  const a={};const l=lessons.find(l=>l.id===id);
  for(let i=0;i<l.quiz.length;i++){const n=answers[i];if(Number.isInteger(n)&&n>=0&&n<l.quiz[i].answers.length)a[i]=n}
  obj.quizAnswers[id]=a;
 }
 for(const [id,note] of Object.entries(x.notes||{})){if(lessonIDs.has(id)&&typeof note==='string')obj.notes[id]=note.slice(0,30000)}
 for(const [id,index] of Object.entries(x.audioIndex||{})){if(lessonIDs.has(id)&&Number.isInteger(index)&&index>=0&&index<30000)obj.audioIndex[id]=index}
 for(const [id,time] of Object.entries(x.audioTime||{})){if(lessonIDs.has(id)&&typeof time==='number'&&time>=0&&time<1000000)obj.audioTime[id]=time}
 for(const [id,rev] of Object.entries(x.reviews||{})){if(lessonIDs.has(id)&&rev&&typeof rev==='object'&&Number.isFinite(Date.parse(rev.due)))obj.reviews[id]={...rev}}
 obj.attemptHistory=Array.isArray(x.attemptHistory)?x.attemptHistory.filter(v=>v&&lessonIDs.has(v.lessonId)&&Number.isFinite(v.score)).slice(-2000):[];
 for(const [id,val] of Object.entries(x.quizAttemptDone||{}))if(lessonIDs.has(id)&&val)obj.quizAttemptDone[id]=true;
 for(const [id,val] of Object.entries(x.exerciseProgress||{}))if(exercises.some(e=>e.id===id)&&val&&typeof val==='object')obj.exerciseProgress[id]={status:['done','open'].includes(val.status)?val.status:'open',note:typeof val.note==='string'?val.note.slice(0,12000):'',updated:val.updated||null};

 if(x.settings&&typeof x.settings==='object'){
  obj.settings.rate=[.8,1,1.15,1.3,1.5].includes(Number(x.settings.rate))?Number(x.settings.rate):1;
  obj.settings.voice=typeof x.settings.voice==='string'?x.settings.voice.slice(0,150):'';
 }
 obj.updated=typeof x.updated==='string'&&!Number.isNaN(Date.parse(x.updated))?x.updated:null;
 if(obj.view==='module'&&!obj.activeModule)obj.view='dashboard';
 return obj
}
const findLesson=id=>lessons.find(l=>l.id===id),findModule=id=>modules.find(m=>m.id===id);
const completed=(id)=>state.lessonDone.includes(id);
const lessonQ=id=>{const l=findLesson(id);const answers=state.quizAnswers[id]||{};return l?l.quiz.filter((x,i)=>answers[i]===x.correct).length:0};
const doneInYear=y=>lessons.filter(l=>findModule(l.moduleId).year===y&&completed(l.id)).length;
const totalInYear=y=>lessons.filter(l=>findModule(l.moduleId).year===y).length;
const pct=(n,d)=>d?Math.round(n/d*100):0;
function save(){state.updated=new Date().toISOString();storage.save(state);cloud.queue(state);renderSave()}
function renderSave(){const el=q('#save-status');if(!el)return;
 const info=storage.quality();const broken=info.mode==='memory';
 el.textContent=broken?'Lernstand NICHT dauerhaft gespeichert':info.mode==='indexeddb'?'Lernstand auf Gerät gespeichert':'Lernstand lokal gespeichert (eingeschränkt)';
 el.classList.toggle('bad',broken||info.mode==='localstorage');el.title=info.lastError||'Lokal in diesem Browser; für den Gerätewechsel JSON exportieren.';
}
async function flushAndShow(){try{await storage.flush()}catch(_){}renderSave()}
function stopAudio(){const mediaState=audioFiles.getState();if(mediaState.loaded&&mediaState.lessonId){state.audioTime[mediaState.lessonId]=mediaState.current;storage.save(state)}audioFiles.unload();audioAvailable=false;runId++;if('speechSynthesis'in window)window.speechSynthesis.cancel();isSpeaking=false;isPaused=false;speechChunks=[];liveLessonId=null}
function navigate(view,opts={}){if(state.view!=='lesson'||view!=='lesson'||opts.lesson&&opts.lesson!==state.activeLesson)stopAudio();state.view=view;if(opts.year)state.year=opts.year;if(opts.lesson)state.activeLesson=opts.lesson;if(opts.module){state.activeModule=opts.module;state.year=findModule(opts.module)?.year||state.year}activeTab=opts.tab||'inhalt';state.tab=activeTab;save();render();window.scrollTo({top:0,behavior:'instant'});if(innerWidth<730)closeDrawer()}
function render(){const main=q('#main');if(!main)return;$$('.nav-link').forEach(b=>b.classList.toggle('active',Boolean(b.dataset.nav===state.view||(b.dataset.year&&['year','module'].includes(state.view)&&+b.dataset.year===state.year))));if(state.view==='dashboard')main.innerHTML=renderHome();else if(state.view==='year')main.innerHTML=renderYear();else if(state.view==='lesson')main.innerHTML=renderLesson();else if(state.view==='module')main.innerHTML=renderModule(state.activeModule);else if(state.view==='settings')main.innerHTML=renderSettings();else if(state.view==='sources')main.innerHTML=renderSources();else if(state.view==='reviews')main.innerHTML=renderReviews();else if(state.view==='stats')main.innerHTML=renderStats();else if(state.view==='practice')main.innerHTML=renderPractice();else if(state.view==='cloud')main.innerHTML=renderCloud();else main.innerHTML=renderHome();connect();renderSave();}
const progress=(p)=>`<div class="track"><div style="width:${Math.max(0,Math.min(100,p))}%"></div></div>`;
function renderHome(){const done=state.lessonDone.length;const last=findLesson(state.activeLesson)||lessons[0];const nextNew=lessons.find(l=>!completed(l.id))||last;return `<div class="content"><div class="hero"><div class="eyebrow">Berufskunde · Lernplattform Version 0.6</div><h1>Elektroinstallateur EFZ<br>Schritt für Schritt lernen.</h1><p>Vier Lehrjahre als fachlicher Lernpfad nach dem bisherigen Bildungsplan 2015. Alle 48 Module sind jetzt als gesprochene Unterrichtseinheiten, Fachbeispiele und Selbsttests verfügbar. Diese erste Inhaltsfassung wird später mit offiziellen Lehrmitteln und der NIN abgeglichen.</p><div class="hero-actions"><button class="btn primary" data-lesson="${safe(last.id)}">▶ Lernen fortsetzen</button><button class="btn ghost" data-lesson="${safe(nextNew.id)}">Nächste offene Lektion</button><button class="btn ghost" data-view="year" data-year="1">Lehrplan ansehen</button></div></div>
<div class="metric-grid"><div class="metric"><strong>${done} / ${lessons.length}</strong><small>Lektionen abgeschlossen</small></div><div class="metric"><strong>${pct(done,lessons.length)} %</strong><small>Aktueller Inhaltsumfang</small></div><div class="metric"><strong>48</strong><small>Module im Vierjahresplan</small></div></div>
<div class="home-actions"><button class="btn teal" data-view="reviews">↺ Wiederholungen (${spaced.due(state).length} fällig)</button><button class="btn" data-view="practice">▤ Vertiefungsaufgaben (${exercises.length})</button><button class="btn" data-view="stats">▥ Lernstatistik</button><button class="btn" data-view="cloud">☁ Cloud-Synchronisierung</button></div>
<div class="section-row"><h2>Deine vier Lehrjahre</h2><span>48 Module mit Lerninhalt · Normendetails werden nachgeprüft</span></div><div class="years-grid">${[1,2,3,4].map((y)=>`<button class="year-card" data-view="year" data-year="${y}"><span class="number">LEHRJAHR 0${y}</span><strong>${['','Grundlagen und Sicherheit','Wechselstrom, Schutz & Planung','Installation und Systeme','Vertiefung und QV'][y]}</strong><p>${y===1?'Mathematik, Grundgrössen, Gleichstrom, Pläne und Werkstoffe':y===2?'Drehstrom, RCD, Leitungen, technische Dokumentation':y===3?'Verteiler, Messungen, Motoren, Gebäudeautomation und PV':'Selektivität, Prüfungsaufgaben und systematische Fehlersuche'}</p>${progress(pct(doneInYear(y),totalInYear(y)))}<div class="small-muted" style="margin-top:8px">${doneInYear(y)} von ${totalInYear(y)} Lektionen abgeschlossen</div></button>`).join('')}</div>
<div class="section-row"><h2>Dein nächster Schritt</h2></div><div class="panel"><div class="eyebrow">Letzter Lernpunkt</div><h3 style="font-size:22px;margin:3px 0 10px">${safe(last.title)}</h3><p style="color:var(--muted)">Modul ${safe(last.moduleId)} · ca. ${last.minutes} Minuten Lernzeit inklusive Aufgaben</p><div style="margin:17px 0">${progress(pct(state.lessonDone.length,lessons.length))}</div><button class="btn teal" data-lesson="${safe(last.id)}">Diese Lektion öffnen →</button></div>
<div class="section-row"><h2>Was noch fehlt</h2></div><div class="source-box">Alle Themen haben jetzt eine erste eigenständige Erklärung. Für eine umfassende EFZ-Prüfungsvorbereitung fehlen jedoch weiterhin der Normenabgleich mit der vollständigen NIN, weitere normengeprüfte Vertiefungsaufgaben, gezeichnete Installations- und Stromlaufpläne sowie die fachkundig begleitete praktische Ausbildung. Die 48 Module sind unsere didaktische Einteilung, keine offizielle Einteilung der Berufslehre.</div><div class="section-row"><h2>Wichtiger Hinweis</h2></div><div class="warning">Das Programm vermittelt Fachwissen, ist aber kein offizieller EFZ-Lehrgang. Die Prüfungszulassung nach Art. 32 BBV und die geforderte betreute elektrotechnische Berufspraxis bleiben unabhängig davon notwendig. Versuche an Netzspannung sind nicht Bestandteil der Selbstlernübungen.</div>
${footer()}</div>`}
function renderYear(){const y=state.year;const mlist=modules.filter(m=>m.year===y);return `<div class="content"><div class="eyebrow">Curriculum · Bildungsplan 2015</div><h1 class="page-title">${y}. Lehrjahr</h1><p class="lead">${['','Sicherheitskultur, Mathematik, Gleichstrom und technische Grundlagen.','Wechselstrom, Drehstrom, Schutzmassnahmen, Erstprüfung und Planung.','Installationen, Steuerungstechnik, Gebäudeautomation, PV und Messungen.','Vertiefung, Fehlersuche, Normenarbeit, Projektdokumentation und QV.'][y]} Die 48 Module sind eine didaktische Aufteilung unseres Arbeitsplans, keine offizielle Modulnummerierung.</p><div class="section-row"><h2>Alle 12 Module</h2><span>${mlist.filter(x=>x.status==='ready').length} mit ersten Unterrichtslektionen</span></div><div class="module-grid">${mlist.map(m=>{const ml=lessons.filter(l=>l.moduleId===m.id);const ready=ml.length>0;return `<article class="module-card"><div class="module-top"><span class="module-id">MODUL ${safe(m.id)}</span><span class="pill ${ready?'ready':''}">${ready?ml.length+' Lektionen bereit':'Curriculum'}</span></div><h3>${safe(m.title)}</h3><p>${safe(m.goals.slice(0,2).join(' · '))}</p><div class="module-actions"><span class="small-muted">${ready?`${ml.filter(l=>completed(l.id)).length}/${ml.length} erledigt`:'Noch nicht ausgearbeitet'}</span><button class="btn tiny ${ready?'teal':''}" data-module="${safe(m.id)}">${ready?'Öffnen':'Lernziele ansehen'} →</button></div></article>`}).join('')}</div><div class="source-box">Grundlage: EIT.swiss Bildungsplan und Berufsfachschullehrplan 2015. Die Module stammen aus dem gemeinsam erstellten 48-Modul-Arbeitsplan; ihre Einteilung ist nicht amtlich.</div>${footer()}</div>`}
function renderModule(id){const m=findModule(id);if(!m)return renderYear();const ml=lessons.filter(l=>l.moduleId===id);const content=`<div class="content"><div class="breadcrumb"><button data-view="year" data-year="${m.year}">← ${m.year}. Lehrjahr</button><span>/</span>Modul ${safe(m.id)}</div><div class="eyebrow">${ml.length?'Basislektion erstellt · Quellenabgleich ausstehend':'Inhalt in Vorbereitung'}</div><h1 class="page-title">${safe(m.title)}</h1><p class="lead">Die nachfolgenden Themen sind im bisherigen Lernplan vorgesehen. Jedes Modul besitzt erste eigene Dozententexte, Aufgaben und Lernkontrollen. Die fachliche Vertiefung und der Abgleich mit der vollständigen NIN sowie den Schulbüchern folgen als spätere Inhaltsversion.</p><div class="section-row"><h2>Was Du beherrschen sollst</h2></div><div class="curriculum-preview"><ul>${m.goals.map(g=>`<li>${safe(g)}</li>`).join('')}</ul><div class="small-muted">Lernzielzuordnung des Arbeitsplans: ${safe(m.reference||'noch zu prüfen')}</div><p class="small-muted">${safe(m.norm)}</p></div><div class="section-row"><h2>Unterrichtslektionen</h2><span>${ml.length} Lektionen</span></div>${ml.length?ml.map((l,i)=>`<article class="lesson-row" style="padding:18px 20px;margin-bottom:9px;display:flex;justify-content:space-between;gap:10px;align-items:center"><div><div class="small-muted">Lektion ${i+1} · ca. ${l.minutes} Min.</div><strong>${safe(l.title)}</strong>${completed(l.id)?'<div class="small-muted" style="color:#0c8066">✓ Lernkontrolle bestanden</div>':''}</div><button class="btn ${completed(l.id)?'':'teal'}" data-lesson="${safe(l.id)}">${completed(l.id)?'Wiederholen':'Lernen'} →</button></article>`).join(''):`<div class="empty-state">Der Lehrplan dieses Moduls ist erfasst, die gesprochenen Unterrichtslektionen und Quizfragen sind noch nicht erstellt. Der Lernstand der bereits fertigen Module bleibt beim Ausbau bestehen.</div>`}<div class="section-row"><h2>Praxisauftrag (nur sichere Lernumgebung)</h2></div><div class="task-card"><p>${safe(m.activity)}</p><div class="task-safe">Arbeiten an 230/400-V-Installationen und spannungsführenden PV-DC-Kreisen gehören ausschliesslich in die berechtigte, fachlich beaufsichtigte Praxis.</div></div>${footer()}</div>`;return content}
function renderLesson(){const l=findLesson(state.activeLesson)||lessons[0];const m=findModule(l.moduleId);const neighbors=lessons.filter(x=>x.moduleId===l.moduleId);const idx=neighbors.findIndex(x=>x.id===l.id);const na=state.audioIndex[l.id]||0;const selected=state.quizAnswers[l.id]||{};const score=lessonQ(l.id);return `<div class="content"><div class="breadcrumb"><button data-view="year" data-year="${m.year}">${m.year}. Lehrjahr</button><span>›</span><button data-module="${safe(m.id)}">Modul ${safe(m.id)}</button><span>›</span> Lektion ${idx+1}</div><div class="lesson-header"><div><div class="eyebrow">Modul ${safe(m.id)} · etwa ${l.minutes} Minuten</div><h1>${safe(l.title)}</h1><p>${completed(l.id)?'✓ Lernkontrolle bestanden · kann jederzeit wiederholt werden':'Dozentenerklärung, Übung, drei Kontrollfragen · erste Unterrichtsfassung'}</p></div><span class="pill ${completed(l.id)?'ready':''}">${completed(l.id)?'Abgeschlossen':'In Arbeit'}</span></div>
<div class="audio-panel"><div class="audio-head"><strong>◉ Dozent anhören</strong><span id="audio-label">${!('speechSynthesis'in window)?'Auf diesem Browser nicht verfügbar':'Start: '+(na+1)+'. Abschnitt'}</span></div><div class="audio-buttons"><button id="audio-play" class="btn play" ${!('speechSynthesis'in window)?'disabled':''}>▶ ${na>0?'Fortsetzen':'Anhören'}</button><button id="audio-back" class="btn">↶ Zurück</button><button id="audio-restart" class="btn">↺ Von vorn</button><button id="audio-stop" class="btn">■ Stopp</button></div><div class="audio-progress">${progress(0)}<div class="small-muted" style="color:#b8d7d7;margin-top:6px">Gerätestimme auf Deutsch · Geschwindigkeit in den Einstellungen wählbar. Der Browser kann die Wiedergabe beim Sperren des Bildschirms unterbrechen.</div></div></div>
<div class="audio-more"><div class="setting-row"><button class="btn tiny" id="media-back">◀ 15 s</button><button class="btn tiny" id="media-forward">15 s ▶</button><button class="btn tiny" id="media-delete">Audiodatei entfernen</button><label class="btn tiny" for="media-import">Audio (MP3/M4A) hinzufügen</label><input type="file" id="media-import" class="sr-only" accept="audio/*,.mp3,.m4a,.wav"/></div><div id="media-status" class="small-muted">Vorlesestimme oder importierte Audiodatei; die Dateien bleiben nur auf diesem Gerät.</div></div>
<div class="tabs"><button class="tab ${activeTab==='inhalt'?'active':''}" data-tab="inhalt">Dozent erklärt</button><button class="tab ${activeTab==='praxis'?'active':''}" data-tab="praxis">Übung & Notizen</button><button class="tab ${activeTab==='quiz'?'active':''}" data-tab="quiz">Wissen prüfen <span style="opacity:.7">(${score}/3)</span></button></div><div id="lesson-body">${renderLessonBody(l)}</div><div class="lesson-foot"><button class="btn" data-module="${safe(m.id)}">← Modulübersicht</button><button class="btn" data-next="${safe(l.id)}">${lessons.findIndex(x=>x.id===l.id)===lessons.length-1?'Zum Lernstand →':'Nächste Lektion →'}</button></div>${footer()}</div>`}
function renderLessonBody(l){if(activeTab==='inhalt')return `<section class="objectives"><h3>Nach dieser Lektion kannst Du …</h3><ul>${l.objectives.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></section>${l.parts.map((p,i)=>`<article class="content-section" id="part-${i}"><div class="eyebrow">Erklärteil ${i+1} von ${l.parts.length}</div><h3>${safe(p.heading)}</h3><p>${safe(p.text)}</p>${p.formula?`<div class="formula">${safe(p.formula)}</div>`:''}</article>`).join('')}${l.moduleId==='1.03'?schematic():''}<div class="source-box"><strong>Quellen- und Normkompass</strong><p style="margin:7px 0">Erste Inhaltsversion. Referenzen sind thematisch zugeordnet, NIN-Detailanforderungen noch nicht vollständig gegengeprüft.</p><ul>${l.references.map(r=>`<li>${safe(r)}${r.includes('NIN')?' – genaue Anforderungen nur mit Originalnorm prüfen':''}</li>`).join('')}</ul>Eigene Unterrichtserklärungen auf Grundlage des fachlichen Lehrplans; keine Wiedergabe des Originalnormtexts.</div>`;
if(activeTab==='praxis')return `<div class="task-card"><div class="eyebrow">Aufgabe zum Anwenden</div><h3>Dein Übungsauftrag</h3><p>${safe(l.task)}</p><div class="task-safe">Sicherheit: nur Papier, Simulation oder geeignete Schutzkleinspannungs-Lernmodelle. Keine selbstständigen Arbeiten an Hausinstallationen oder PV-DC-Strings.</div><label class="notes-label" for="note-field">Meine Notizen und Ergebnisse</label><textarea class="notes" id="note-field" placeholder="Hier kannst Du Deinen Rechenweg, deine Erkenntnisse oder offene Fragen festhalten."></textarea><p class="checkline">Speicherung automatisch auf diesem Gerät; für langfristige Sicherung bitte regelmässig exportieren.</p></div>`;
const answers=state.quizAnswers[l.id]||{};const score=lessonQ(l.id);return `<div class="objectives"><strong>Grundlagen-Selbsttest</strong><p style="margin:6px 0 0;font-size:13px">Beantworte alle drei Fragen. Ab zwei richtigen Antworten ist die Lernkontrolle bestanden. Wiederholen ist jederzeit möglich.</p></div>${l.quiz.map((x,i)=>`<div class="quiz-card"><div class="eyebrow">Frage ${i+1} von ${l.quiz.length}</div><h3>${safe(x.question)}</h3>${x.answers.map((a,j)=>{const answered=answers[i]!==undefined;const cls=answered?(j===x.correct?'correct':j===answers[i]?'wrong':''):'';return `<button class="option ${cls} ${answers[i]===j?'selected':''}" data-answer="${i}:${j}"><span class="bubble">${'ABC'[j]}</span>${safe(a)}</button>`}).join('')}${answers[i]!==undefined?`<div class="feedback">${answers[i]===x.correct?'✓ Richtig.':'Noch nicht richtig.'} ${safe(x.why)}</div>`:''}</div>`).join('')}<div class="quiz-result ${score<2?'low':''}"><strong>${Object.keys(answers).length===l.quiz.length?(score>=2?'Lernkontrolle bestanden':'Noch nicht bestanden'):'Du kannst die Fragen direkt beantworten.'}</strong><div>${score} von ${l.quiz.length} Antworten richtig</div>${Object.keys(answers).length===l.quiz.length?`<div style="margin-top:11px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="quiz-reset">Fragen wiederholen</button>${score>=2?'<span style="font-size:13px;align-self:center">✓ Lernstand wurde gespeichert.</span>':''}</div>`:''}</div>`;
}
function schematic(){return `<svg class="schematic" viewBox="0 0 600 155" role="img" aria-label="Vereinfachtes Schaltbild: 12-Volt-Gleichspannungsquelle mit Widerstand"><path d="M135 30 H445 V122 H135 V30" fill="none" stroke="#1e6573" stroke-width="3"/><path d="M135 64 v21 m-17 0 h34 m-25 10 h16" stroke="#1e6573" stroke-width="3" fill="none"/><rect x="277" y="18" width="85" height="23" rx="4" fill="#fff" stroke="#1e6573" stroke-width="2"/><text x="320" y="35" font-size="13" text-anchor="middle" fill="#154b56">R = 120 Ω</text><text x="92" y="95" font-size="13" fill="#1e6573">12 V</text><text x="468" y="79" font-size="13" fill="#1e6573">I = 0,1 A</text><text x="300" y="144" text-anchor="middle" font-size="11" fill="#71838c">Schematische Modellschaltung, kein Installationsplan</text></svg>`}
function renderSettings(){const info=storage.quality(),voiceSelect=voiceOptions();return `<div class="content"><div class="eyebrow">Lernplattform v0.6</div><h1 class="page-title">Einstellungen und Datensicherung</h1><p class="lead">Dein Lernstand wird lokal gespeichert, während Du arbeitest. Sichere ihn zusätzlich als Datei, damit er bei Verlust des Geräts oder gelöschten Browserdaten wiederhergestellt werden kann.</p>
<div class="setting-card"><h3>Gesprochene Lektionen</h3><p>Die Vorlesefunktion verwendet die Stimmen des Geräts. iOS kann die Wiedergabe bei gesperrtem Display unterbrechen.</p><label for="voice">Stimme wählen</label><div class="setting-row"><select id="voice" class="select">${voiceSelect}</select><select id="rate" class="select"><option value="0.8" ${state.settings.rate==.8?'selected':''}>0,8×</option><option value="1" ${state.settings.rate==1?'selected':''}>1,0×</option><option value="1.15" ${state.settings.rate==1.15?'selected':''}>1,15×</option><option value="1.3" ${state.settings.rate==1.3?'selected':''}>1,3×</option><option value="1.5" ${state.settings.rate==1.5?'selected':''}>1,5×</option></select><button class="btn" id="voice-test">▶ Stimme testen</button></div></div>
<div class="setting-card"><h3>Speicherstatus</h3><p id="storage-status">${safe(info.mode==='indexeddb'?'IndexedDB aktiv · lokaler Checkpoint zusätzlich gesichert':info.mode==='localstorage'?'Eingeschränkter Modus: localStorage-Checkpoint': 'Warnung: Nur flüchtiger Speicher')}</p><p class="small-muted">Letzte Änderung: ${state.updated?safe(new Date(state.updated).toLocaleString('de-CH')):'noch keine'} · Optionale Cloud-Synchronisierung unter Cloud & Geräte</p>${info.lastError?`<div class="warning">${safe(info.lastError)}</div>`:''}<div class="setting-row"><button class="btn" id="persist-request">Dauerhaften Browser-Speicher anfragen</button><button class="btn" id="save-check">Speicher prüfen</button></div><p id="storage-message" class="small-muted" aria-live="polite"></p></div>
<div class="setting-card"><h3>Externe Sicherungsdatei</h3><p>Die JSON-Sicherung enthält alle abgeschlossenen Lektionen, Antworten, Notizen, Einstellungen und Audio-Positionen. Nur eine heruntergeladene und separat aufbewahrte Datei ist ein geräteunabhängiges Backup.</p><div class="setting-row"><button class="btn teal" id="export">↓ JSON exportieren</button><label class="btn" for="import" style="cursor:pointer">↑ JSON importieren</label><input id="import" type="file" accept=".json,application/json" class="sr-only"></div><p class="small-muted">Sicherungen aus v0.1, v0.2 und v0.3 können importiert werden.</p></div>
<div class="setting-card"><h3>Lokale Wiederherstellungspunkte</h3><p>Zusätzlich zur regulären Speicherung werden bis zu fünf lokale Momentaufnahmen vorgehalten. Sie liegen im selben Browser und ersetzen daher keinen externen Export.</p><div class="setting-row"><button class="btn" id="snapshot-make">＋ Wiederherstellungspunkt erstellen</button></div><div id="snapshot-list" class="small-muted">Momentaufnahmen werden geladen …</div></div>
<div class="setting-card"><h3>Updates und Offlinebetrieb</h3><p>In der gehosteten PWA werden neue Versionen zuerst heruntergeladen. Die Installation erfolgt auf Deine Bestätigung. Alle 145 bestehenden Lektionen behalten ihre Kennungen.</p><p id="update-info" class="small-muted">${location.protocol==='file:'?'Lokale HTML-Datei: keine App-Updates möglich.':location.protocol==='https:'?'Prüfe, ob eine neue Version verfügbar ist …':'Die PWA erfordert HTTPS oder localhost.'}</p><button class="btn" id="update-check">Nach Updates suchen</button> <button class="btn teal" id="update-apply" ${waitingWorker?'':'hidden'}>Update installieren und neu laden</button>${location.protocol==='file:'?'<div class="warning">Du hast die HTML-Datei lokal geöffnet. Je nach Browser werden Daten nicht dauerhaft oder zwischen Dateien geteilt. Für längere Nutzung bitte die PWA über eine feste HTTPS-Adresse verwenden und einen JSON-Export aufbewahren.</div>':''}</div>
<div class="setting-card"><h3>Zurücksetzen</h3><p>Löscht Deine Antworten, Notizen und Lernmarkierungen in dieser App. Lokale Wiederherstellungspunkte bleiben erhalten, damit sich ein Irrtum rückgängig machen lässt.</p><button class="btn" id="reset" style="color:#a14343">Aktuellen Lernstand zurücksetzen</button></div>${footer()}</div>`}

function renderReviews(){const due=spaced.due(state),pending=due.map(id=>findLesson(id)).filter(Boolean),soon=Object.entries(state.reviews).filter(([id,r])=>!due.includes(id)&&lessonIDs.has(id)).sort((a,b)=>a[1].due.localeCompare(b[1].due)).slice(0,12);return `<div class="content"><div class="eyebrow">Lernen mit Wiederholung · Version 0.6</div><h1 class="page-title">Wiederholungsplan</h1><p class="lead">Nach einer vollständig bearbeiteten Lernkontrolle wird ein Wiederholungsdatum gesetzt. Ab 80 % richtigen Antworten verlängert sich der Abstand; andernfalls folgt eine Wiederholung am nächsten Tag. Ein bestandener Selbsttest ist keine EFZ-Prüfungszulassung.</p><div class="metric-grid"><div class="metric"><strong>${due.length}</strong><small>Heute fällig</small></div><div class="metric"><strong>${Object.keys(state.reviews).length}</strong><small>Geplante Lektionen</small></div><div class="metric"><strong>${state.attemptHistory.length}</strong><small>Quizversuche</small></div></div><div class="section-row"><h2>Heute wiederholen</h2></div>${pending.length?pending.map(l=>`<article class="lesson-row review-row"><div><strong>${safe(l.title)}</strong><div class="small-muted">${safe(l.moduleId)} · letztes Ergebnis ${state.reviews[l.id]?.lastScore}/${state.reviews[l.id]?.total}</div></div><button class="btn teal" data-review-open="${safe(l.id)}">Quiz starten</button></article>`).join(''):'<div class="panel">Noch keine Wiederholungen fällig. Bearbeite zuerst eine Lernkontrolle.</div>'}<div class="section-row"><h2>Als Nächstes</h2></div>${soon.length?soon.map(([id,r])=>{const l=findLesson(id);return `<article class="lesson-row review-row"><div><strong>${safe(l.title)}</strong><div class="small-muted">${safe(new Date(r.due).toLocaleDateString('de-CH'))} · Intervall ${r.interval} Tage</div></div><button class="btn" data-lesson="${safe(id)}">Öffnen</button></article>`}).join(''):'<div class="panel">Noch keine zukünftigen Wiederholungen eingeplant.</div>'}${footer()}</div>`}
function renderStats(){const st=spaced.stats(state,lessons,modules),all=state.attemptHistory;return `<div class="content"><div class="eyebrow">Lernanalyse · Version 0.6</div><h1 class="page-title">Deine Lernstatistik</h1><p class="lead">Die Werte stammen aus Deinen gespeicherten Übungen und Quizversuchen. Sie zeigen den Stand dieser Lernplattform, keine prognostizierte EFZ-Prüfungsnote.</p><div class="metric-grid"><div class="metric"><strong>${st.completed}/${st.total}</strong><small>Abgeschlossene Lektionen</small></div><div class="metric"><strong>${st.average} %</strong><small>Ø korrekte Quizantworten</small></div><div class="metric"><strong>${st.dueIds.length}</strong><small>Wiederholungen fällig</small></div></div><div class="panel"><h2>Vier Lehrjahre</h2>${st.years.map(y=>`<div class="stats-line"><span>${y.year}. Lehrjahr</span><div class="stats-bar">${progress(y.percent)}</div><strong>${y.done}/${y.total} · ${y.percent} %</strong></div>`).join('')}</div><div class="section-row"><h2>Quizversuche im Verlauf</h2></div><div class="panel"><div class="small-muted">${all.length} protokollierte Versuche</div>${all.slice(-12).reverse().map(a=>`<div class="history-line"><span>${safe(findLesson(a.lessonId)?.title||a.lessonId)}</span><span>${a.score}/${a.total} · ${safe(new Date(a.at).toLocaleDateString('de-CH'))}</span></div>`).join('')||'<p>Bearbeite ein Quiz, um Lernversuche zu sehen.</p>'}</div><div class="section-row"><h2>Nachbearbeiten</h2></div><div class="panel">${st.hard.length?`Diese Lektionen wurden zuletzt unter 80 % gelöst: ${st.hard.map(id=>`<button class="btn tiny" data-lesson="${safe(id)}">${safe(findLesson(id)?.title||id)}</button>`).join(' ')}`:'Aktuell keine Lernkontrollen unter 80 % vorgemerkt.'}</div>${footer()}</div>`}
function renderPractice(){const y=exSelected,arr=exercises.filter(e=>findModule(e.moduleId)?.year===y);const done=exercises.filter(e=>state.exerciseProgress[e.id]?.status==='done').length;return `<div class="content"><div class="eyebrow">Fachliche Vertiefung · Version 0.6</div><h1 class="page-title">Vertiefungsaufgaben</h1><p class="lead">${exercises.length} eigenständig entwickelte Aufgaben mit Musterlösungen, Rechenwegen und Kontrollkriterien. Der fachliche Normenabgleich steht teilweise noch aus. Keine offiziellen QV-Aufgaben.</p><div class="panel"><strong>${done} von ${exercises.length} Aufgaben als bearbeitet markiert</strong><div class="setting-row">${[1,2,3,4].map(n=>`<button class="btn ${y===n?'teal':''}" data-ex-select="${n}">${n}. Lehrjahr</button>`).join('')}</div></div>${arr.map(e=>`<article class="practice-card"><div class="eyebrow">${safe(e.moduleId)} · ${safe(e.id)} · ${state.exerciseProgress[e.id]?.status==='done'?'✓ Bearbeitet':'Noch offen'}</div><h2>${safe(e.title)}</h2><p>${safe(e.prompt)}</p><div class="setting-row"><button class="btn" data-ex-solution="${safe(e.id)}">${exerciseShow[e.id]?'Musterlösung verbergen':'Musterlösung ansehen'}</button><button class="btn ${state.exerciseProgress[e.id]?.status==='done'?'':'teal'}" data-ex-done="${safe(e.id)}">✓ Bearbeitet</button>${state.exerciseProgress[e.id]?.status==='done'?`<button class="btn" data-ex-open="${safe(e.id)}">Zurücksetzen</button>`:''}</div>${exerciseShow[e.id]?`<div class="solution"><strong>Musterlösung</strong><p>${safe(e.solution)}</p><strong>Kontrollpunkte</strong><ul>${e.checkpoints.map(x=>`<li>${safe(x)}</li>`).join('')}</ul><small>${safe(e.normStatus)}</small></div>`:''}</article>`).join('')}${footer()}</div>`}
function renderCloud(){const c=cloud.get();return `<div class="content"><div class="eyebrow">Optionale Gerätesynchronisierung · Version 0.5</div><h1 class="page-title">Cloud-Synchronisierung</h1><p class="lead">Die App funktioniert vollständig ohne Konto. Cloud-Synchronisierung benötigt ein eigenes, von Dir eingerichtetes Supabase-Projekt mit aktivierter Row Level Security. Ohne Einrichtung werden keine Lernstände übertragen.</p><div class="warning">Vor der ersten Synchronisierung bitte eine JSON-Sicherung exportieren. Bei abweichenden Ständen entscheidest Du ausdrücklich, welcher Stand übernommen oder ob zusammengeführt wird. Der Betrieb eines Cloud-Dienstes ist nicht Teil dieses lokalen HTML-Pakets.</div><div class="setting-card"><h3>1. Supabase-Projekt verbinden</h3><p>Projekt-URL und ausschliesslich den öffentlichen Publishable-/Anon-Key eintragen. Niemals einen geheimen Service-Role-Key verwenden. Die zugehörige SQL-Datei aus dem PWA-Paket zuerst im SQL-Editor ausführen.</p><label>Projekt-URL <input id="cloud-url" class="cloud-field" placeholder="https://xyz.supabase.co" value="${safe(c.config?.url||'')}"></label><label>Öffentlicher API-Key <input id="cloud-key" class="cloud-field" type="password" placeholder="sb_publishable_…" value=""></label><button class="btn" data-cloud-action="configure">Projekt speichern</button><p class="small-muted">${c.configured?'Projekt bereits lokal konfiguriert. Schlüssel wird aus Sicherheitsgründen nicht angezeigt.':'Noch kein Cloud-Projekt hinterlegt.'}</p></div><div class="setting-card"><h3>2. Benutzerkonto</h3><p>Mit E-Mail und Passwort anmelden. Wenn die E-Mail-Bestätigung aktiviert ist, nach der Registrierung zuerst den Bestätigungslink öffnen.</p><label>E-Mail <input id="cloud-email" class="cloud-field" type="email" autocomplete="email" placeholder="deine@email.ch" value="${safe(c.email)}"></label><label>Passwort <input id="cloud-password" class="cloud-field" type="password" autocomplete="current-password" placeholder="Passwort (wird nicht gespeichert)"></label><div class="setting-row"><button class="btn teal" data-cloud-action="login">Anmelden</button><button class="btn" data-cloud-action="signup">Registrieren</button><button class="btn" data-cloud-action="logout">Abmelden</button></div></div><div class="setting-card"><h3>3. Fortschritt abgleichen</h3><p><strong>Status:</strong> ${safe(c.status)}</p><p class="small-muted">Cloud-Revision: ${c.remoteRevision||'–'} · letzte lokale Synchronisierung: ${c.revision||'–'} · Automatik: ${c.enabled?'aktiv':'pausiert'}</p><div class="setting-row"><button class="btn" data-cloud-action="check">Cloud-Stand prüfen</button><button class="btn" data-cloud-action="cloud">Cloud übernehmen</button><button class="btn" data-cloud-action="local">Lokalen Stand hochladen</button><button class="btn teal" data-cloud-action="merge">Stände zusammenführen</button></div><p class="small-muted">Zusammenführen vereinigt abgeschlossene Lektionen und Versuche; bei gleichzeitig bearbeiteten Notizen gilt der zuletzt aktualisierte Stand. Vor jedem manuellen Abgleich wird eine lokale Sicherung angelegt. Läuft die Cloud-Revision davon, stoppt der automatische Upload statt unbemerkt zu überschreiben.</p><div id="cloud-message" aria-live="polite"></div></div>${footer()}</div>`}
function renderSources(){const src=[['EIT.swiss – Elektroinstallateur EFZ','https://www.eit.swiss/de/bildung/grundbildung/elektroinstallateurin-efz'],['Bildungsplan 2015 (48 Seiten)','https://www.eitzentralschweiz.ch/fileadmin/user_upload/documents/Berufsbildung/Grundbildung/Elektroinstallateurin_EFZ/_de/2015_EI_Bildungsplan.pdf'],['Lehrplan Berufsfachschule 2015 (35 Seiten)','https://www.eit-fr.ch/fileadmin/user_upload/documents/Berufsbildung/Grundbildung/Elektroinstallateurin_EFZ/_de/2015_EI_Lehrplan_Berufsfachschule.pdf'],['Suva 5+5 lebenswichtige Regeln','https://www.suva.ch/de-ch/praevention/lebenswichtige-regeln-und-bestimmungen/lebenswichtige-regeln-am-arbeitsplatz/filme-lebenswichtige-regeln-elektrizitaet'],['ESTI – Übersicht Installationsbewilligungen','https://www.esti.admin.ch/de/themen/bewilligungen-niv-uebersicht/bewilligungen-niv'],['NIV – SR 734.27','https://www.fedlex.admin.ch/eli/cc/2002/22/de'],['EIT.swiss – Musterprüfung praktische Arbeit','https://www.eitgeneve.ch/fileadmin/user_upload/documents/Berufsbildung/Grundbildung/Elektroinstallateurin_EFZ/_de/2015_EI_Musterserie_PA.pdf']];return `<div class="content"><div class="eyebrow">Transparenz</div><h1 class="page-title">Quellen, Umfang und Grenzen</h1><p class="lead">Diese Version enthält 48 Module und 145 bearbeitbare Unterrichtslektionen, die als vorläufige erste Inhaltsfassung erstellt wurden. Die fachliche Grundlage orientiert sich am bisherigen Bildungsplan von 2015. Es handelt sich um selbst formulierte Lerntexte, nicht um ein offizielles EIT-Lehrmittel.</p><div class="panel"><h2 style="margin:0 0 13px">Offizielle Grundlagen</h2>${src.map(([n,u])=>`<p style="margin:9px 0"><a href="${safe(u)}" target="_blank" rel="noopener noreferrer">${safe(n)} ↗</a></p>`).join('')}</div><div class="section-row"><h2>Was diese Version bietet</h2></div><div class="panel"><p><strong>Fertig:</strong> vier Lehrjahre als Navigationsstruktur, 48 Module als Lehrplan, 145 Unterrichtslektionen mit Dozententexten, 435 Quizfragen, Lernnotizen, Sprachausgabe, automatischer Fortschritt, Backup-Export und -Import.</p><p><strong>Noch nicht fertig:</strong> die sorgfältige fachliche Einzelprüfung mit vollständiger NIN, offiziell validierte QV-Aufgaben, interaktive Schaltungs-Simulationen und professionell eingesprochene Audiodateien. 25 eigene vertiefte Lernaufgaben mit Musterlösungen sind verfügbar. Dies wird nicht als abgeschlossen ausgewiesen.</p><p><strong>Prüfungsrecht:</strong> Das Programm ersetzt weder die gesetzlich erforderliche Berufspraxis noch die praktische EFZ-Abschlussprüfung oder die Zulassungsverfügung. Das vor 2030 gewünschte alte QV ist mit der zuständigen Stelle abzuklären.</p></div>${footer()}</div>`}
const footer=()=>`<div class="footer">Elektroinstallateur EFZ · Eigenständiges Lernprogramm · Stand November 2026 · Keine Installationsbewilligung · Version 0.6</div>`;
function voiceOptions(){const vv=('speechSynthesis'in window?window.speechSynthesis.getVoices():[]).filter(v=>/^de\b|^de[-_]/i.test(v.lang));return [`<option value="">Automatisch (Deutsch)</option>`,...vv.map(v=>`<option value="${safe(v.voiceURI)}" ${state.settings.voice===v.voiceURI?'selected':''}>${safe(v.name)} (${safe(v.lang)})</option>`)].join('')}
function currentChunks(l){const pieces=[];for(const p of l.parts){pieces.push(p.heading+'.');const ss=p.text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[p.text];for(const sentence of ss){let s=sentence.trim();if(!s)continue;if(s.length<=190)pieces.push(s);else{const words=s.split(/\s+/);let cur='';for(const w of words){if((cur+' '+w).length>180&&cur){pieces.push(cur.trim());cur=''}cur+=' '+w}if(cur.trim())pieces.push(cur.trim())}}}return pieces}
function updateAudioUI(){if(audioAvailable){const s=audioFiles.getState();const l=q('#audio-label');if(l)l.textContent=`Audiodatei · ${fmtTime(s.current)} / ${fmtTime(s.duration)}`;const bar=q('.audio-panel .track>div');if(bar)bar.style.width=pct(s.current,s.duration)+'%';const play=q('#audio-play');if(play)play.textContent=s.playing?'Ⅱ Pause':'▶ Weiter';return;}const l=findLesson(state.activeLesson);if(!l)return;const parts=currentChunks(l),i=Math.max(0,Math.min(state.audioIndex[l.id]||0,parts.length));const label=q('#audio-label');if(label)label.textContent=(isSpeaking?(isPaused?'Pausiert · ':'Es läuft · '):'Bereit · ')+`${i} / ${parts.length} Sprechabschnitte`;const bar=q('.audio-panel .track>div');if(bar)bar.style.width=pct(i,parts.length)+'%';const play=q('#audio-play');if(play)play.textContent=isSpeaking?(isPaused?'▶ Weiter':'Ⅱ Pause'):(i>0?'▶ Fortsetzen':'▶ Anhören')}
function fmtTime(s){s=Math.floor(Number(s)||0);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
async function audioLoad(){const l=findLesson(state.activeLesson);if(!l||state.view!=='lesson')return;audioAvailable=await audioFiles.prepare(l.id,()=>{if(state.view==='lesson'){updateAudioUI();void audioLoad();}},(id,secs,duration)=>{if(id!==state.activeLesson||(secs!==0&&Date.now()-audioPositionTick<3000))return;audioPositionTick=Date.now();state.audioTime[id]=secs;save();},state.audioTime[l.id]||0);audioFiles.setRate(state.settings.rate||1);audioFiles.setMetadata(l.title);const info=q('#media-status');if(info)info.textContent=audioAvailable?'Lokale Audioaufnahme aktiv – Fortschritt und Wiedergabezeit werden gespeichert.':'Gerätestimme aktiv. Optional kannst Du eine eigene Audioaufnahme für diese Lektion importieren.';if(q('#media-delete'))q('#media-delete').hidden=!audioAvailable;updateAudioUI()}
function playAudio(){if(audioAvailable){const s=audioFiles.getState();if(s.playing)audioFiles.pause();else audioFiles.play().catch(e=>{audioError=e.message;const label=q('#media-status');if(label)label.textContent='Audio-Wiedergabe fehlgeschlagen: '+audioError});return;}if(!('speechSynthesis'in window))return;const l=findLesson(state.activeLesson);if(!l)return;const synth=window.speechSynthesis;if(isSpeaking){if(isPaused){synth.resume();isPaused=false}else{synth.pause();isPaused=true}updateAudioUI();return}stopAudio();isSpeaking=true;liveLessonId=l.id;speechChunks=currentChunks(l);const token=runId;let index=Math.min(state.audioIndex[l.id]||0,speechChunks.length-1);function next(){if(token!==runId||!isSpeaking||state.activeLesson!==l.id)return;if(index>=speechChunks.length){isSpeaking=false;isPaused=false;state.audioIndex[l.id]=0;save();updateAudioUI();return}state.audioIndex[l.id]=index;save();updateAudioUI();const utter=new SpeechSynthesisUtterance(speechChunks[index]);utter.lang='de-CH';utter.rate=Number(state.settings.rate)||1;utter.pitch=1;const selected=synth.getVoices().find(v=>v.voiceURI===state.settings.voice);const fallback=synth.getVoices().find(v=>/^de-CH/i.test(v.lang))||synth.getVoices().find(v=>/^de/i.test(v.lang));if(selected||fallback)utter.voice=selected||fallback;utter.onend=()=>{if(token!==runId)return;index++;state.audioIndex[l.id]=index;save();next()};utter.onerror=()=>{isSpeaking=false;updateAudioUI()};synth.speak(utter)}next()}
function audioBack(){if(audioAvailable){audioFiles.seek(-15);return;}const l=findLesson(state.activeLesson);if(!l)return;const newIdx=Math.max(0,(state.audioIndex[l.id]||0)-1);stopAudio();state.audioIndex[l.id]=newIdx;save();updateAudioUI()}
function audioRestart(){if(audioAvailable){audioFiles.seek(-1e9);state.audioTime[state.activeLesson]=0;save();return;}const l=findLesson(state.activeLesson);if(!l)return;stopAudio();state.audioIndex[l.id]=0;save();updateAudioUI()}
function answerQuiz(i,j){const l=findLesson(state.activeLesson);if(!l)return;state.quizAnswers[l.id]??={};state.quizAnswers[l.id][i]=j;const ans=state.quizAnswers[l.id];if(l.quiz.every((x,i)=>ans[i]!==undefined)){if(lessonQ(l.id)>=2&&!completed(l.id))state.lessonDone.push(l.id);if(!state.quizAttemptDone[l.id]){const score=lessonQ(l.id),total=l.quiz.length;state.reviews[l.id]=spaced.review(state.reviews[l.id],score,total);state.attemptHistory.push({id:l.id+'-'+Date.now(),lessonId:l.id,score,total,at:new Date().toISOString()});state.attemptHistory=state.attemptHistory.slice(-2000);state.quizAttemptDone[l.id]=true;}}save();const y=window.scrollY;render();window.scrollTo(0,y)}
function nextLesson(){const i=lessons.findIndex(l=>l.id===state.activeLesson);if(i>=0&&i<lessons.length-1)navigate('lesson',{lesson:lessons[i+1].id});else navigate('dashboard')}
function connect(){for(const b of $$('[data-view]'))b.onclick=()=>navigate(b.dataset.view,{year:Number(b.dataset.year)||null});for(const b of $$('[data-lesson]'))b.onclick=()=>navigate('lesson',{lesson:b.dataset.lesson});for(const b of $$('[data-module]'))b.onclick=()=>navigate('module',{module:b.dataset.module});for(const b of $$('[data-tab]'))b.onclick=()=>{activeTab=b.dataset.tab;state.tab=activeTab;save();stopAudio();render()};for(const b of $$('[data-answer]'))b.onclick=()=>{const [i,j]=b.dataset.answer.split(':').map(Number);answerQuiz(i,j)};for(const b of $$('[data-next]'))b.onclick=nextLesson;
q('#audio-play')?.addEventListener('click',playAudio);q('#audio-back')?.addEventListener('click',audioBack);q('#audio-restart')?.addEventListener('click',audioRestart);q('#audio-stop')?.addEventListener('click',()=>{stopAudio();updateAudioUI();void audioLoad()});
q('#media-back')?.addEventListener('click',()=>{if(audioAvailable)audioFiles.seek(-15);else audioBack()});
q('#media-forward')?.addEventListener('click',()=>{if(audioAvailable)audioFiles.seek(15);else{state.audioIndex[state.activeLesson]=(state.audioIndex[state.activeLesson]||0)+3;stopAudio();save();updateAudioUI()}});
q('#media-import')?.addEventListener('change',async e=>{try{const f=e.target.files?.[0];if(!f)return;stopAudio();await audioFiles.importFile(state.activeLesson,f);await audioLoad();alert('Audioaufnahme für diese Lektion offline gespeichert. Sie ist nicht Teil des JSON-Fortschrittsexports.')}catch(err){alert('Audioimport fehlgeschlagen: '+err.message)}finally{e.target.value=''}});
q('#media-delete')?.addEventListener('click',()=>openDialog('Audioaufnahme löschen','Die lokal gespeicherte Audiodatei dieser Lektion wird entfernt. Fortschritt und Lerntext bleiben erhalten.',async()=>{await audioFiles.remove(state.activeLesson);audioAvailable=false;await audioLoad()}));
q('#quiz-reset')?.addEventListener('click',()=>{delete state.quizAnswers[state.activeLesson];delete state.quizAttemptDone[state.activeLesson];state.lessonDone=state.lessonDone.filter(x=>x!==state.activeLesson);save();render()});
const note=q('#note-field');if(note){note.value=state.notes[state.activeLesson]||'';note.oninput=()=>{state.notes[state.activeLesson]=note.value;save()}};
q('#rate')?.addEventListener('change',e=>{state.settings.rate=+e.target.value;save()});q('#voice')?.addEventListener('change',e=>{state.settings.voice=e.target.value;save()});q('#voice-test')?.addEventListener('click',()=>{stopAudio();if(!('speechSynthesis'in window))return;const utter=new SpeechSynthesisUtterance('Guten Tag. Ich bin deine Stimme für das Lernprogramm Elektroinstallateur EFZ. Wir lernen die Fachthemen Schritt für Schritt.');utter.lang='de-CH';utter.rate=Number(state.settings.rate)||1;const v=window.speechSynthesis.getVoices().find(v=>v.voiceURI===state.settings.voice);if(v)utter.voice=v;window.speechSynthesis.speak(utter)});
for(const b of $$('[data-ex-select]'))b.onclick=()=>{exSelected=Number(b.dataset.exSelect);render()};
for(const b of $$('[data-ex-solution]'))b.onclick=()=>{exerciseShow[b.dataset.exSolution]=!exerciseShow[b.dataset.exSolution];render()};
for(const b of $$('[data-ex-done]'))b.onclick=()=>{const id=b.dataset.exDone;state.exerciseProgress[id]={status:'done',note:state.exerciseProgress[id]?.note||'',updated:new Date().toISOString()};save();render()};
for(const b of $$('[data-ex-open]'))b.onclick=()=>{const id=b.dataset.exOpen;state.exerciseProgress[id]={status:'open',note:state.exerciseProgress[id]?.note||'',updated:new Date().toISOString()};save();render()};
for(const b of $$('[data-review-open]'))b.onclick=()=>navigate('lesson',{lesson:b.dataset.reviewOpen,tab:'quiz'});
for(const b of $$('[data-cloud-action]'))b.onclick=async()=>{const label=q('#cloud-message');try{const action=b.dataset.cloudAction;if(action==='configure'){cloud.config(q('#cloud-url').value,q('#cloud-key').value);if(label)label.textContent='Projekt gespeichert. Du kannst Dich anmelden.';}
else if(action==='login'||action==='signup'){const logged=await cloud.signIn(q('#cloud-email').value,q('#cloud-password').value,action==='signup');if(label)label.textContent=logged?'Angemeldet. Bitte den Stand abgleichen.':'Bitte E-Mail bestätigen und erneut anmelden.';}
else if(action==='logout'){cloud.signOut();if(label)label.textContent='Abgemeldet.';}
else if(action==='check'){await cloud.inspect();}
else if(['cloud','local','merge'].includes(action)){await storage.snapshot(state,'vor Cloud-Abgleich');await cloud.choose(action);}
render();}catch(e){if(label)label.textContent='Fehler: '+e.message;}};
q('#snapshot-make')?.addEventListener('click',async()=>{const ok=await storage.snapshot(state,'manuell');await renderSnapshots();alert(ok?'Wiederherstellungspunkt lokal erstellt. Für eine geräteunabhängige Sicherung bitte JSON exportieren.':'Lokale Momentaufnahme nicht möglich. Bitte JSON exportieren.')});
q('#persist-request')?.addEventListener('click',async()=>{const ok=await storage.requestPersistence();const e=q('#storage-message');if(e)e.textContent=ok?'Browser hat dauerhafte Speicherung bestätigt. Trotzdem externe Sicherung empfehlen.':'Browser hat dauerhafte Speicherung nicht bestätigt. Verwende den JSON-Export.'});
q('#save-check')?.addEventListener('click',async()=>{const info=await storage.flush();const e=q('#storage-message');if(e)e.textContent='Speichermodus: '+info.mode+(info.lastError?' · '+info.lastError:' · letzter Schreibvorgang abgeschlossen');renderSave()});
q('#update-check')?.addEventListener('click',async()=>{const el=q('#update-info');if(!pwaRegistration){if(el)el.textContent='Nur in der gehosteten PWA verfügbar.';return}try{await pwaRegistration.update();if(el&&!waitingWorker)el.textContent='Prüfung abgeschlossen. Aktuell kein Update bereit.'}catch(e){if(el)el.textContent='Updateprüfung fehlgeschlagen: '+e.message}});
q('#update-apply')?.addEventListener('click',applyUpdate);
if(state.view==='settings')renderSnapshots();
q('#export')?.addEventListener('click',exportSave);q('#import')?.addEventListener('change',importSave);q('#reset')?.addEventListener('click',()=>openDialog('Fortschritt zurücksetzen','Alle Antworten, Lernnotizen und Audio-Positionen in diesem Browser werden gelöscht. Exportiere vorher zur Sicherheit eine Sicherungsdatei.',async()=>{await storage.snapshot(state,'vor Zurücksetzen');stopAudio();state=fresh();save();await flushAndShow();navigate('dashboard')}));if(state.view==='lesson')updateAudioUI()}
function exportSave(){const b=new Blob([JSON.stringify({app:'Elektro EFZ Lernprogramm',version:2,created:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download='elektro-efz-lernstand-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function importSave(ev){const file=ev.target.files?.[0];if(!file)return;try{
 if(file.size>5e6)throw Error('Datei zu gross (max. 5 MB)');
 const obj=JSON.parse(await file.text());
 if(obj.app!=='Elektro EFZ Lernprogramm'||![1,2].includes(obj.version)||!obj.data||!Array.isArray(obj.data.lessonDone))throw Error('Keine kompatible Lernstand-Sicherung');
 const data=normalize(obj.data);
 openDialog('Lernstand importieren','Der aktuelle Lernstand wird durch die Sicherung ersetzt. Bestehende Wiederherstellungspunkte bleiben erhalten. Fortfahren?',async()=>{
  await storage.snapshot(state,'vor Dateiimport');stopAudio();state=data;state.view='dashboard';activeTab=state.tab;save();await flushAndShow();render()
 });
 }catch(e){alert('Import nicht möglich: '+e.message)}finally{ev.target.value=''}
}
async function renderSnapshots(){const el=q('#snapshot-list');if(!el)return;
 try{const items=await storage.listSnapshots();if(!q('#snapshot-list'))return;
  el.innerHTML=items.length?items.map((s,i)=>`<div class="snapshot-item"><span>${safe(new Date(s.at).toLocaleString('de-CH'))}<br><small>${safe(s.reason||'Sicherung')} · ${Array.isArray(s.state?.lessonDone)?s.state.lessonDone.length:0} Lektionen</small></span><button class="btn tiny" data-restore="${i}">Wiederherstellen</button></div>`).join(''):'Noch keine lokalen Momentaufnahmen verfügbar.';
  el.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const snap=items[Number(b.dataset.restore)];if(!snap)return;
   openDialog('Stand wiederherstellen',`Der lokale Stand vom ${new Date(snap.at).toLocaleString('de-CH')} ersetzt den aktuellen Lernstand. Fortfahren?`,async()=>{
     await storage.snapshot(state,'vor Wiederherstellung');stopAudio();state=normalize(snap.state);state.view='dashboard';activeTab=state.tab;save();await flushAndShow();render();
   })
  });
 }catch(e){el.textContent='Lokale Momentaufnahmen können nicht gelesen werden: '+e.message}
}
function onUpdateReady(worker){waitingWorker=worker;const btn=q('#update-apply');if(btn)btn.hidden=false;
 const info=q('#update-info');if(info)info.textContent='Neue Version bereit. Installation erst nach Deiner Bestätigung.';
 showUpdateBanner()
}
function showUpdateBanner(){if(!waitingWorker||q('#update-banner'))return;const d=document.createElement('div');d.id='update-banner';d.className='update-banner';d.innerHTML='<span>Eine neue Version ist bereit. Dein Lernstand bleibt gespeichert.</span><button class="btn tiny teal" id="update-now">Jetzt aktualisieren</button><button class="btn tiny" id="update-later">Später</button>';
 document.body.appendChild(d);q('#update-now').onclick=applyUpdate;q('#update-later').onclick=()=>d.remove()}
async function applyUpdate(){if(!waitingWorker)return;updateAccepted=true;await flushAndShow();waitingWorker.postMessage({type:'SKIP_WAITING'});q('#update-banner')?.remove()}
async function setupUpdates(){if(!('serviceWorker'in navigator)||!['https:','http:'].includes(location.protocol))return;
 if(location.protocol==='http:'&&!['localhost','127.0.0.1'].includes(location.hostname))return;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updateAccepted)location.reload()});
 try{pwaRegistration=await navigator.serviceWorker.register('./sw.js');
  if(pwaRegistration.waiting&&navigator.serviceWorker.controller)onUpdateReady(pwaRegistration.waiting);
  pwaRegistration.addEventListener('updatefound',()=>{const w=pwaRegistration.installing;if(!w)return;
   w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)onUpdateReady(w)})});
  const label=q('#update-info');if(label&&!waitingWorker)label.textContent='PWA aktiv. Neue Versionen werden nur nach Bestätigung aktiviert.';
 }catch(e){const label=q('#update-info');if(label)label.textContent='PWA nicht verfügbar: '+e.message}
}
function openDialog(title,msg,onConfirm){const backdrop=document.createElement('div');backdrop.className='dialog-overlay';backdrop.innerHTML=`<div class="dialog" role="dialog" aria-modal="true"><h2>${safe(title)}</h2><p>${safe(msg)}</p><div class="actions"><button class="btn" id="modal-cancel">Abbrechen</button><button class="btn primary" id="modal-ok">Bestätigen</button></div></div>`;document.body.appendChild(backdrop);backdrop.querySelector('#modal-cancel').onclick=()=>backdrop.remove();backdrop.querySelector('#modal-ok').onclick=()=>{backdrop.remove();onConfirm()};backdrop.addEventListener('click',e=>{if(e.target===backdrop)backdrop.remove()})}
function closeDrawer(){q('#side')?.classList.remove('open');q('.side-backdrop')?.remove();q('#hamb')?.setAttribute('aria-expanded','false')}
q('#hamb')?.addEventListener('click',()=>{const on=q('#side').classList.toggle('open');q('#hamb').setAttribute('aria-expanded',String(on));if(on){const d=document.createElement('div');d.className='side-backdrop';d.onclick=closeDrawer;document.body.appendChild(d)}else q('.side-backdrop')?.remove()});
q('#logo')?.addEventListener('click',e=>{e.preventDefault();navigate('dashboard')});for(const b of $$('.nav-link')){if(b.dataset.nav==='dashboard')b.onclick=()=>navigate('dashboard');else if(b.dataset.nav==='settings')b.onclick=()=>navigate('settings');else if(b.dataset.nav==='sources')b.onclick=()=>navigate('sources');else if(['practice','reviews','stats','cloud'].includes(b.dataset.nav))b.onclick=()=>navigate(b.dataset.nav);else if(b.dataset.year)b.onclick=()=>navigate('year',{year:+b.dataset.year})}
if('speechSynthesis'in window)window.speechSynthesis.onvoiceschanged=()=>{if(state.view==='settings'){const s=q('#voice');if(s)s.innerHTML=voiceOptions()}};
window.addEventListener('pagehide',()=>{if(isSpeaking)stopAudio();save();void storage.flush()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(isSpeaking&&!isPaused&&'speechSynthesis'in window){window.speechSynthesis.pause();isPaused=true}save();void storage.flush()}else if(state.view==='lesson')updateAudioUI()});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&state.view==='lesson'&&!['TEXTAREA','INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();playAudio()}});
async function initialize(){try{const loaded=await storage.init();state=normalize(loaded||fresh())}catch(e){console.warn('Lernstand konnte nicht geladen werden',e);state=fresh()}
 activeTab=state.tab||'inhalt';render();await storage.weeklySnapshot(state);void setupUpdates();
 void cloud.start({getState:()=>state,onReceive:async raw=>{await storage.snapshot(state,'vor Cloud-Übernahme');stopAudio();state=normalize(raw);state.view='dashboard';activeTab=state.tab;state.updated=new Date().toISOString();storage.save(state);await storage.flush();render()},onStatus:msg=>{cloudNotice=msg;const el=q('#cloud-message');if(el)el.textContent=msg}});

}
initialize();
})();
